<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#050b10"><title>{{$vps->hostname?:('VPS #'.$vps->id)}} · Nodexa Control</title><link rel="stylesheet" href="{{asset('css/nodexa-vps-control.css')}}?v=0.16.2"></head><body><header class="vc-top"><div class="vc-topin"><a class="vc-brand" href="/client"><span class="vc-logo">N</span><span>Nodexa<small>VPS CONTROL</small></span></a><a class="vc-back" href="/client#vps">← Control Center</a></div></header><main class="vc-wrap">@if(session('success'))<div class="vc-alert ok">{{session('success')}}</div>@endif @if($errors->any())<div class="vc-alert err">{{$errors->first()}}</div>@endif @if($apiError)<div class="vc-alert err">Provider: {{$apiError}}</div>@endif @php($currentPassword=$storedPassword??($info['password']??$info['root_password']??$info['rootPassword']??$info['admin_password']??$info['adminPassword']??null)) @php($osDisplay=(string)($info['os_name']??$info['operatingSystem']??'')) @php($osCollection=collect($oses)) @php($selectedOs=$osCollection->first(function($os) use ($vps){return (string)($os['id']??$os['value']??$os['template_id']??'')===(string)$vps->os_id;})) @php($selectedOsName=is_array($selectedOs)?(string)($selectedOs['name']??$selectedOs['label']??$selectedOs['title']??''):'') @php($isWindows=stripos($osDisplay.' '.$selectedOsName,'windows')!==false) @php($currentUser=$isWindows?'Administrator':'root')<section class="vc-hero"><div class="vc-title"><div class="vc-server-icon">◆</div><div><div class="vc-eyebrow">NODEXA VPS CONTROL</div><h1>{{$vps->hostname?:('VPS #'.$vps->id)}}</h1><div class="vc-meta">Service #{{$vps->id}} · Provider #{{$vps->provider_server_id?:'—'}}</div></div></div><span class="vc-status">{{str_replace('_',' ',$vps->status)}}</span></section><section class="vc-stats"><div class="vc-stat"><span>IP-adresse</span><strong>{{$vps->ip_address?:($info['ip_address']??$info['ip']??'Afventer IP')}}</strong></div><div class="vc-stat"><span>Operativsystem</span><strong>{{$info['os_name']??$info['operatingSystem']??($selectedOsName?:('OS ID '.($vps->os_id?:'—')))}}</strong></div><div class="vc-stat"><span>Hostname</span><strong>{{$vps->hostname?:($info['hostname']??'—')}}</strong></div><div class="vc-stat"><span>Provider status</span><strong>{{$info['status']??$vps->status}}</strong></div></section><div class="vc-grid"><div><div class="vc-label">SERVERKONTROL</div><section class="vc-card"><div class="vc-card-head"><span>Power controls</span><small>Live provider actions</small></div><div class="vc-card-body vc-power">@foreach(['boot'=>['▶ Start',''],'shutdown'=>['■ Luk ned','orange'],'restart'=>['↻ Genstart','secondary'],'poweroff'=>['⚠ Tving sluk','red']] as $action=>$x)<form method="POST" action="/client/vps/{{$vps->id}}/power">@csrf<input type="hidden" name="action" value="{{$action}}"><button class="vc-btn {{$x[1]}}">{{$x[0]}}</button></form>@endforeach</div></section><section class="vc-card"><div class="vc-card-head"><span>Serveradgang</span><small>{{$isWindows?'Remote Desktop':'SSH'}}</small></div><div class="vc-card-body vc-credentials"><div class="vc-fieldbox"><label>ADMINISTRATORKONTO</label><strong>{{$currentUser}}</strong></div><div class="vc-fieldbox"><label>ADGANGSKODE</label>@if($currentPassword)<div class="vc-pass"><code id="vps-password" data-password="{{e($currentPassword)}}">••••••••••••</code><button type="button" class="vc-btn vc-mini secondary" onclick="togglePass(this)">Vis</button><button type="button" class="vc-btn vc-mini secondary" onclick="copyPass(this)">Kopiér</button></div>@else<div class="vc-note">Ingen adgangskode er gemt endnu. Nulstil den én gang for at generere og gemme en ny krypteret adgangskode.</div>@endif</div></div></section></div><aside><div class="vc-label">ADMINISTRATION</div><section class="vc-card"><div class="vc-card-head"><span>Sikkerhed</span><small>Password reset</small></div><form class="vc-card-body" method="POST" action="/client/vps/{{$vps->id}}/reset-password">@csrf<div class="vc-note">Nodexa vælger automatisk korrekt administratorkonto ud fra operativsystemet.</div><div class="vc-fieldbox" style="margin-top:10px"><label>KONTO</label><strong>{{$currentUser}}</strong><div class="vc-note">{{$isWindows?'Windows Administrator':'Linux root'}}</div></div><button class="vc-btn" style="margin-top:10px">Generér ny adgangskode</button></form></section><section class="vc-card vc-danger"><div class="vc-card-head"><span>Danger zone</span><small>Reinstall</small></div><form class="vc-card-body" method="POST" action="/client/vps/{{$vps->id}}/rebuild" onsubmit="return confirm('Alt data på VPS’en slettes permanent. Fortsæt?')">@csrf<div class="vc-note"><strong style="color:#ff929d">Geninstallation sletter alle filer permanent.</strong> Vælg det operativsystem der skal installeres.</div><select class="vc-select" name="os_id" required><option value="">Vælg operativsystem...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{$oid==$vps->os_id?'selected':''}}>{{$on}}</option>@endforeach</select><input type="hidden" name="confirm" value="REINSTALL"><button class="vc-btn red">Geninstaller VPS</button></form></section></aside></div><div class="vc-footer">Nodexa VPS Control · Service #{{$vps->id}}</div></main><script>function togglePass(b){var e=document.getElementById('vps-password'),s=e.dataset.shown==='1';e.textContent=s?'••••••••••••':e.dataset.password;e.dataset.shown=s?'0':'1';b.textContent=s?'Vis':'Skjul'}function copyPass(b){var e=document.getElementById('vps-password');if(!e)return;navigator.clipboard.writeText(e.dataset.password);var t=b.textContent;b.textContent='Kopieret ✓';setTimeout(function(){b.textContent=t},1200)}</script></body></html>